from pathlib import Path
import hashlib,json,sqlite3,stat,sys
out=Path(__file__).resolve().parent;f=json.loads((out/'fixture.json').read_text());workspace=Path(f['workspace_root']);root=Path(f['root']);label=sys.argv[1]
def snap():return {str(p.relative_to(workspace)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in workspace.rglob('*') if p.is_file()}
assert snap()==json.loads((out/'repository-before.json').read_text());assert hashlib.sha256(Path(f['hook']).read_bytes()).hexdigest()==f['hook_sha256'];runs=(root/'hook-runs').read_text().splitlines();assert runs==['run']*(1 if label=='rejection' else 2)
c=sqlite3.connect('file:'+f['state']+'/state.db?mode=ro',uri=True);ops={k:json.loads(v) for k,v in c.execute('select id,payload from write_operations')};assert all(not op['published'] for op in ops.values());assert ops['892338d5-7a92-408c-be61-1440638a17c7']['phase']=='blocked';assert ops['7345051b-e229-4345-946f-18aaf56a0501']['phase']=='cancelled_before_publication';
if label!='rejection':
 assert ops['e56ba4ec-2f34-4c0c-adcc-af0f69cc2958']['phase']=='cancelled_before_publication' and ops['7b5a0835-9372-4ddc-bc4c-f9c35ffefb14']['phase']=='cancelled_before_publication'
assert set(c.execute('select worktree_id,revoked from write_trust'))=={(f['entries'][f[k]],0) for k in ['parent','child']};assert c.execute('pragma integrity_check').fetchone()[0]=='ok';records={'operations':dict(c.execute('select id,payload from write_operations')),'batches':dict(c.execute("select key,value from state where key like 'batch:%'"))};(out/('records-'+label+'.json')).write_text(json.dumps(records,indent=2)+'\n');proof={'repository_exact_original_bytes_modes':True,'no_publication':True,'hook_runs':len(runs),'hook_bytes_unchanged':True,'parent_stopped_before_execution':True,'exact_authorized_parent_child_trust':True,'control_untrusted':True,'integrity':'ok'};(out/('verify-'+label+'.json')).write_text(json.dumps(proof,indent=2)+'\n');print(proof)
